import {VERSION,STORAGE_KEY,FIELDS,LABS,CLASS_CARDS,TRANSFER_CARDS,START_SETTINGS,tracePrism,thermalAtTime,calcExperiment,settingSignature,meaningfulDifference,newProgress,safeProgress,labCount,firstPassCount,mastery,documentEvidence} from './domain.mjs';

const $=q=>document.querySelector(q);
const root=$('#app');
let state=load();let raf=0,sceneStarted=0,shownWrong='',showHint=false,lastFrame=0,feedbackMessage='';
function load(){try{return safeProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)))}catch(_){return newProgress()}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(_){/* privé gezinme: çalışma bellek içinde sürer */}}
function fmt(x){return Math.round(x*100)/100}
const field=id=>FIELDS.find(x=>x.id===id);
const lab=id=>LABS.find(x=>x.id===id);
function icon(name,size=20){
  const paths={beaker:'<path d="M9 3h6M10 3v7l-5.5 9a2 2 0 0 0 1.7 3h11.6a2 2 0 0 0 1.7-3L14 10V3"/><path d="M8 16h8"/>',
  compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.2 5.8L8 16l2.2-5.8L16 8Z"/>',
  layers:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',
  chart:'<path d="M3 3v18h18M7 16l4-5 3 3 5-7"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
  refresh:'<path d="M3 12a9 9 0 1 0 3-7M3 3v6h6"/>', sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Zm7 14 .7 1.3L21 19l-1.3.7L19 21l-.7-1.3L17 19l1.3-.7L19 17Z"/>',
  book:'<path d="M4 5a2 2 0 0 1 2-2h14v17H6a2 2 0 0 0-2 2V5Zm0 15a2 2 0 0 1 2-2h14"/>',
  home:'<path d="m3 11 9-8 9 8v10h-6v-6H9v6H3V11Z"/>',volume:'<path d="M5 9H2v6h3l5 4V5L5 9Zm9-2a6 6 0 0 1 0 10m3-13a10 10 0 0 1 0 16"/>'};
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.compass}</svg>`;
}
function sectionName(){return {explore:'Deney masası',classify:'Alan haritası',transfer:'Transfer görevi',report:'Görev raporu'}[state.view]}
function navButton(view,text,ic,disabled=false){return `<button class="navlink ${state.view===view?'current':''}" data-view="${view}" ${disabled?'disabled':''} aria-current="${state.view===view?'page':'false'}">${icon(ic,19)}<span>${text}</span>${disabled?icon('lock',14):''}</button>`}
function fieldMark(id){const f=field(id);return `<span class="domainmark" style="--domain:${f.color}">${f.symbol}</span>`}
function layout(content){const count=labCount(state);const total=Math.round((count/4)*55+(state.classAnswers.length/8)*25+(state.transferAnswers.length/4)*20);
return `<div class="app-shell"><aside class="sidebar">
  <div class="brand"><div class="brand-icon">${icon('beaker',24)}</div><div><strong>FİZİK<span>ATLASI</span></strong><small>Keşif laboratuvarı</small></div></div>
  <div class="course-card"><span class="eyebrow">GÖREV DOSYASI / 01</span><b>Fizik Bilimi ve Kariyer Keşfi</b><span class="subtle">9. Sınıf · Bölüm 1</span><div class="progress-rail"><span style="width:${total}%"></span></div><div class="course-foot"><span>Keşif ilerlemesi</span><b>${total}%</b></div></div>
  <div class="nav-heading">ARAŞTIRMA</div><nav class="side-nav" aria-label="Oyun bölümleri">${navButton('explore','Deney masası','beaker')}${navButton('classify','Alan haritası','layers',count<4)}${navButton('transfer','Son görev','compass',state.classAnswers.length<8)}${navButton('report','Araştırma raporu','chart')}</nav>
  <div class="side-bottom"><div class="helper-badge">${icon('sparkles',16)} Fizik tek cevap değildir; bir keşif yoludur.</div><small class="subtle">Bağımsız prototip · Veriler yalnız bu tarayıcıda</small></div>
</aside><main class="main"><header class="topbar"><div class="breadcrumbs">9. SINIF <span>/</span> ÜNİTE 1 <span>/</span> <b>${sectionName()}</b></div><div class="top-actions"><span class="secure-dot"></span><span>Çevrimdışı çalışır</span><button class="circle-btn" data-action="help" title="Nasıl oynanır?" aria-label="Nasıl oynanır?">?</button></div></header><div class="main-inner">${content}</div>
<footer class="footer"><span>Fizik Atlası · Laboratuvar 01 · v${VERSION}</span><span>Şemalar öğretim amaçlıdır; gerçek deneyin yerini almaz.</span></footer></main>
<nav class="mobile-nav" aria-label="Mobil oyun bölümleri">${navButton('explore','Deney','beaker')}${navButton('classify','Alanlar','layers',count<4)}${navButton('transfer','Görev','compass',state.classAnswers.length<8)}${navButton('report','Rapor','chart')}</nav></div><div id="toast" role="status" aria-live="polite"></div>${!state.missionStarted?intro():''}`}
function intro(){return `<div class="intro-overlay" role="dialog" aria-modal="true" aria-label="Bilim merkezi görevi"><div class="intro-panel"><div class="intro-top">${icon('beaker',20)}  ATLAS ARAŞTIRMA MERKEZİ  /  İLK GÖREV</div><div class="intro-orbit"><div class="orbits"><i></i><i></i><i></i><i></i><strong>F</strong></div></div><span class="eyebrow">HOŞ GELDİN, ARAŞTIRMACI</span><h1>Evren bir soru.<br><em>Cevabı keşfet.</em></h1><p>Bilim merkezinin dört deney odası açıldı. Önce tahmin et, deney yap, sonuçlarını kaydet. Sonra sekiz fizik alanını doğru araştırmalara eşleştir.</p><div class="intro-metrics"><span><b>4</b> canlı deney</span><span><b>8</b> alan</span><span><b>1</b> keşif görevi</span></div><button class="button primary wide" data-action="start">Laboratuvara gir ${icon('arrow',18)}</button><small>İnternet ve hesap gerekmez. Video yerine gerçek etkileşim.</small></div></div>`}
function headerTag(text){return `<span class="eyebrow tag-dot">${text}</span>`}
function heroText(){return `<div class="hero"><div class="hero-copy">${headerTag('ARAŞTIRMA PROGRAMI  /  FİZ.9.1.2')}<h1>Fiziği <em>keşfet.</em><br>Alanları birleştir.</h1><p>Görünmeyeni görünür kıl. Kontrolleri değiştir, deneyleri karşılaştır ve kendi sonuçlarınla düşün.</p><div class="hero-pills"><span>${icon('beaker',15)} 4 canlı deney</span><span>${icon('compass',15)} 8 uzmanlık alanı</span></div></div><div class="hero-decoration" aria-hidden="true"><span class="orbit orbit-a"></span><span class="orbit orbit-b"></span><span class="orbit orbit-c"></span><span class="hero-core">✳</span><span class="hlabel l1">IŞIK</span><span class="hlabel l2">KUVVET</span><span class="hlabel l3">ENERJİ</span></div></div>`}
function experimentView(){const l=lab(state.activeLab),rec=state.labs[l.id],uniq=new Set(rec.measurements.map(x=>x.key)).size;
const stations=LABS.map(st=>{const done=state.labs[st.id].completed;return `<button class="station ${st.id===l.id?'selected':''}" data-lab="${st.id}" aria-pressed="${st.id===l.id}"><span class="station-no">${st.chapter}</span><span class="station-ico">${fieldMark(st.field)}</span><span class="station-name">${st.title}</span><small>${st.caption}</small>${done?`<span class="station-tick">${icon('check',14)}</span>`:''}</button>`}).join('');
const old=rec.measurements.at(-1);
return `${heroText()}<div class="section-head"><div><span class="eyebrow muted">DENEY LABORATUVARLARI</span><h2>Keşif istasyonları</h2></div><div class="pill">${labCount(state)} / 4 tamamlandı</div></div><div class="station-grid">${stations}</div>
<section class="lab-surface"><div class="lab-left"><div class="lab-header"><div><span class="eyebrow">DENEY ${l.chapter} <span class="mini-dot"></span> ${l.tag.toUpperCase()}</span><h2>${l.title}</h2><p>${l.mission}</p></div><span class="tag" aria-label="Kazanım">FİZ.9.1.2</span></div><div class="scene-frame"><div class="scene-hud"><span><i class="live-dot"></i> CANLI SİMÜLASYON</span><span id="scene-status">${l.id==='magnet'?'MIKNATISI SÜRÜKLEYEBİLİRSİN':'PARAMETREYİ DEĞİŞTİR'}</span></div><canvas id="labCanvas" role="img" aria-label="${l.mission}. Kontrollerle deneydeki fiziksel değişimi etkileyebilirsin."></canvas><span class="scene-corner">MODEL / ${l.chapter}</span></div><div class="lab-legend"><span>${icon('compass',15)} ${l.adjustment}</span><span class="mini-label">SİMÜLASYON · EĞİTİM MODELİ</span></div></div>
<div class="lab-right"><div class="control-title"><span>01 / PARAMETRELER</span><span class="state-label">${icon('sparkles',15)} ETKİLEŞİMLİ</span></div><div class="controls">${controls(l.id)}</div><div class="control-separator"></div>
<div class="prediction"><div class="step-heading"><span class="step-dot">1</span><b>Önce tahmin et</b></div><p>${l.question}</p><div class="answers">${l.options.map((x,i)=>`<button data-predict="${i}" class="answer ${rec.prediction===i?'selected':''}" aria-pressed="${rec.prediction===i}">${x}<span class="option-key">${'ABC'[i]}</span></button>`).join('')}</div></div>
<button class="button primary wide run-button" data-action="run" ${rec.prediction===null?'disabled':''}>${icon('beaker',18)} Deneyi çalıştır ${icon('arrow',18)}</button>
<div class="measure-summary"><div class="summary-icon">${icon('chart',20)}</div><div><b id="last-reading">${old?old.result:'Ölçüm bekleniyor'}</b><small>${uniq}/2 farklı koşul kaydedildi ${uniq>=2?'· Karşılaştırma hazır':''}</small></div></div>
${uniq>=2?explainStep(l,rec):`<div class="locked-hint">${icon('lock',17)} Açıklama için iki farklı koşulda deney yap.</div>`}
</div></section>${completedFooter()}`}
function controls(id){const s=state.settings[id];
const range=(key,title,min,max,unit,value)=>`<label class="range-label" for="ctrl-${key}"><span>${title}</span><b id="val-${key}">${value}${unit}</b></label><input type="range" min="${min}" max="${max}" step="1" id="ctrl-${key}" data-control="${key}" value="${s[key]}" aria-label="${title}"/><div class="range-ends"><span>${min}${unit}</span><span>${max}${unit}</span></div>`;
const pick=(key,choices)=>`<div class="segmented" role="group" aria-label="${key==='surface'?'Yüzey türü':key==='beam'?'Işık rengi':'Malzeme'}">${choices.map(([val,text])=>`<button data-setting="${key}" data-value="${val}" class="${s[key]===val?'selected':''}" aria-pressed="${s[key]===val}">${text}</button>`).join('')}</div>`;
switch(id){case 'mechanics':return `${range('angle','Eğim açısı',5,45,'°',s.angle)}<label class="mini-title">Yüzey dokusu</label>${pick('surface',[['smooth','Pürüzsüz'],['rough','Pürüzlü']])}`;
case 'optics':return `<label class="mini-title">Işık kaynağı</label>${pick('beam',[['white','Beyaz'],['red','Kırmızı'],['blue','Mavi']])}${range('angle','Giriş yönü',-20,20,'°',s.angle)}`;
case 'magnet':return `${range('position','Mıknatıs konumu',14,68,'%',s.position)}${range('power','Alan gücü',0,100,'%',s.power)}<p class="control-tip">İpucu: sahnede mıknatısa dokunarak da taşıyabilirsin.</p>`;
case 'thermal':return `<label class="mini-title">Çubuk malzemesi</label>${pick('material',[['metal','Metal'],['wood','Ahşap']])}${range('temperature','Kaynak sıcaklığı',40,100,'°C',s.temperature)}`;
}}
function explainStep(l,rec){return `<div class="reason-step"><div class="step-heading"><span class="step-dot amber">2</span><b>Şimdi açıkla</b></div><p>${l.explainQuestion}</p><div class="answers">${l.explainOptions.map((x,i)=>`<button data-reason="${i}" class="answer ${rec.reason===i?'selected':''}" ${rec.completed?'disabled':''} aria-pressed="${rec.reason===i}">${x}<span class="option-key">${'ABC'[i]}</span></button>`).join('')}</div><button class="button ${rec.completed?'success':'secondary'} wide" data-action="verify-reason" ${rec.completed?'disabled':''}>${rec.completed?`${icon('check',16)} Keşif kaydedildi`:'Açıklamamı doğrula'}</button>${rec.reasonAttempts>0&&!rec.completed?'<div class="feedback warning">Açıklamanı yeniden düşün. Ölçümleri karşılaştırıp bir daha dene.</div>':''}${rec.completed?`<div class="feedback correct">${icon('check',17)} <span>${l.science}</span></div>`:''}</div>`}
function completedFooter(){const done=labCount(state);if(done<4)return `<div class="tip-strip">${icon('sparkles',18)} <span>Her istasyonda farklı ayarlarda iki deney kaydet. Dört istasyonu tamamladığında keşiflerinle alan haritasını açacaksın.</span></div>`;return `<div class="unlock-strip"><div><b>${icon('check',20)} 4 / 4 istasyon tamamlandı</b><p>Artık fizik alanlarını yeni olaylarla eşleştirmeye hazırsın.</p></div><button class="button primary" data-view="classify">Alan haritasına geç ${icon('arrow',17)}</button></div>`}
function banner(eyebrow,title,sub){return `<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${sub}</p></div>`}
function optionBoard(type,card){const selected=type==='transfer'?state.transferIndex:state.classIndex;return `<div class="field-grid">${FIELDS.map((f,i)=>`<button class="field-choice" data-${type==='transfer'?'transfer':'class'}="${f.id}"><span class="field-choice-icon">${fieldMark(f.id)}</span><span><b>${f.name}</b><small>${f.description}</small></span><span class="choice-letter">${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div>`}
function classifyView(){if(labCount(state)<4)return gate('Önce deney istasyonlarını tamamla.','explore');const idx=state.classIndex;if(idx>=8)return `<div class="congrats"><div class="medal">${icon('layers',36)}</div>${banner('İLK ANALİZ TAMAMLANDI','Alan haritası oluşturuldu.','Sekiz farklı olayı fizik alt dallarıyla ilişkilendirdin. Şimdi hiç görmediğin örneklerde de bunu kullanabilir misin?')}<div class="score-tiles"><span><b>${firstPassCount(state.classAnswers)}/8</b><small>İlk denemede doğru</small></span><span><b>${state.classMistakes}</b><small>Yanlış deneme</small></span></div><button class="button primary" data-view="transfer">Son göreve geç ${icon('arrow',17)}</button></div>`;
const c=CLASS_CARDS[idx];return `${banner('02 / ALAN HARİTASI','Hangi fizik alanı?','İstasyonlarda gözlediklerini kullan. Her olayı araştıran temel fizik alanını seç.')}<div class="quiz-layout"><div class="case-panel"><div class="quiz-top"><span class="eyebrow">OLAY KARTI ${String(idx+1).padStart(2,'0')}</span><span>${idx+1} / ${CLASS_CARDS.length}</span></div><div class="quiz-progress">${CLASS_CARDS.map((x,i)=>`<i class="${i<idx?'filled':i===idx?'active':''}"></i>`).join('')}</div><div class="case-art"><span class="case-art-symbol">${['◈','◇','⌁','≋','◎','✳','▦','✺'][idx]}</span><span class="case-glow"></span></div><h2>${c.title}</h2><p>${c.body}</p><div class="question-label">Bu olayın temel çalışma alanı nedir?</div>${state.classCurrentHint?`<div class="feedback hint">İpucu: ${c.tip}</div>`:''}<button class="text-button" data-action="hint">${icon('sparkles',17)} İpucu ${state.classCurrentHint?'görüntülendi':'göster'} (ölçüme yazılır)</button></div><div class="option-panel"><div class="control-title"><span>FİZİK ALANINI SEÇ</span><span class="state-label">8 BİLİM ALANI</span></div>${optionBoard('class',c)}<div class="answer-feedback" id="answer-feedback" role="status" aria-live="polite"></div></div></div>`}
function transferView(){if(state.classAnswers.length<8)return gate('Önce sekiz olayı sınıflandır.','classify');const idx=state.transferIndex;if(idx>=4)return `${banner('03 / UYGULAMA','Yeni durum, aynı fizik.','Daha önce görmediğin örneklerde bilgini kullandın. Sonuçları inceleyelim.')}<div class="transfer-finish"><div class="finish-orb">${icon('check',54)}</div><h2>Görev tamamlandı.</h2><p>İlk denemede ${firstPassCount(state.transferAnswers)} / 4 yeni olayı doğru sınıflandırdın.</p><button class="button primary" data-view="report">Araştırma raporunu aç ${icon('arrow',18)}</button></div>`;
const c=TRANSFER_CARDS[idx];return `${banner('03 / TRANSFER GÖREVİ','Bilinmeyeni çöz.','İpucu yok. Laboratuvarda keşfettiğin fikri yeni bir olaya uygula.')}<div class="quiz-layout"><div class="case-panel final-case"><div class="quiz-top"><span class="eyebrow">BAĞIMSIZ GÖREV ${String(idx+1).padStart(2,'0')}</span><span>${idx+1} / ${TRANSFER_CARDS.length}</span></div><div class="quiz-progress">${TRANSFER_CARDS.map((x,i)=>`<i class="${i<idx?'filled':i===idx?'active':''}"></i>`).join('')}</div><div class="case-art"><span class="case-art-symbol">✧</span><span class="case-glow"></span></div><h2>${c.title}</h2><p>${c.body}</p><div class="question-label">Bu problemin merkezindeki fizik alanı hangisi?</div><div class="note-caution">Yardım kapalı · İlk yanıtın değerlendirme için kaydedilir.</div></div><div class="option-panel"><div class="control-title"><span>BAĞIMSIZ SEÇİM</span><span class="state-label">4 YENİ OLAY</span></div>${optionBoard('transfer',c)}<div class="answer-feedback" id="answer-feedback" role="status" aria-live="polite"></div></div></div>`}
function gate(message,view){return `${banner('KİLİTLİ ETAP','Yeni bir keşif seni bekliyor.',message)}<button class="button primary" data-view="${view}">Geri dön ${icon('arrow',17)}</button>`}
function reportView(){const m=mastery(state),p=documentEvidence(state);const cls=Math.min(8,state.classAnswers.length),tr=Math.min(4,state.transferAnswers.length);return `${banner('04 / ARAŞTIRMA RAPORU','Keşif günlüğün.','Ölçümlerine, denemelerine ve öğrendiğini yeni durumlarda kullanma becerine bak.')}<div class="report-header"><div class="report-stamp">${icon(m.pass?'check':'chart',38)}</div><div><span class="eyebrow">FİZ.9.1.2 · KAZANIM GÖSTERGESİ</span><h2>${m.pass?'Güçlü öğrenme kanıtı':'Keşif devam ediyor'}</h2><p>${m.pass?'Deney, sınıflandırma ve yeni durumlarda uygulama ölçütlerini tamamladın.':'Bazı adımlar henüz tamamlanmadı veya pekiştirme gerekli. Bir kez daha deney yapabilirsin.'}</p></div></div><div class="report-stats"><div><b>${m.count}<span>/4</span></b><small>Deney istasyonu</small></div><div><b>${m.classified}<span>/8</span></b><small>İlk denemede sınıflandırma</small></div><div><b>${m.transferred}<span>/4</span></b><small>Bağımsız transfer</small></div><div><b>${state.hints}</b><small>Alınan ipucu</small></div></div><div class="report-bottom"><div class="report-panel"><h3>İstasyon kayıtları</h3>${LABS.map(l=>{const r=state.labs[l.id];return `<div class="report-line">${fieldMark(l.field)}<div><b>${l.title}</b><small>${new Set(r.measurements.map(x=>x.key)).size} farklı ölçüm</small></div><span class="${r.completed?'done-text':'pending-text'}">${r.completed?'TAMAMLANDI':'BEKLİYOR'}</span></div>`}).join('')}</div><div class="report-panel"><h3>Sonuç ve sonraki adım</h3><p class="report-note">Birinci ünite dört kazanım içerir. Bu oyun, ağırlıklı olarak <b>FİZ.9.1.2</b> için öğrenme kanıtı üretir; FİZ.9.1.1'e giriş yapar. Bilim insanları (9.1.3) ve kariyer araştırması (9.1.4) ileride açılacaktır.</p><div class="check-row">${icon('check',17)} Kayıtlar yalnızca bu cihazdaki tarayıcıda tutulur.</div><button class="button secondary wide" data-action="export">${icon('book',16)} Raporu JSON olarak indir</button><button class="button ghost wide" data-action="reset">${icon('refresh',15)} Yalnız bu oyun ilerlemesini sıfırla</button></div></div><div class="sources-strip"><b>Müfredat bağlantısı</b><span>FİZ.9.1.1–9.1.4 · 9. sınıf fizik / ünite 1</span></div>`}
function render(){cancelAnimationFrame(raf);root.innerHTML=layout(({explore:experimentView,classify:classifyView,transfer:transferView,report:reportView})[state.view]());save();if(state.view==='explore')initCanvas();}
function toast(text,type='info'){let el=$('#toast');if(!el)return;el.textContent=text;el.className='visible '+type;clearTimeout(toast.t);toast.t=setTimeout(()=>{if(el)el.className=''},3800)}
function navigate(view){if(view==='classify'&&labCount(state)<4){toast('Önce dört istasyonu tamamla.','warn');return;}if(view==='transfer'&&state.classAnswers.length<8){toast('Önce alan haritasını tamamla.','warn');return;}state.view=view;shownWrong='';showHint=false;feedbackMessage='';render();window.scrollTo({top:0,behavior:'smooth'})}
function record(){let id=state.activeLab,l=lab(id),rec=state.labs[id];if(rec.prediction===null){toast('Deneyden önce tahmin yap.','warn');return;}const settings={...state.settings[id]},result=calcExperiment(id,settings),key=settingSignature(id,settings);let reading=result.value||result.caption;const found=rec.measurements.find(x=>x.key===key);if(found){toast('Bu ayarı zaten kaydettin. Farklı bir koşul dene.','warn');sceneStarted=performance.now();return;}if(rec.measurements.length&&!rec.measurements.some(x=>meaningfulDifference(id,settings,x.settings))){toast('Karşılaştırma için ayarı daha belirgin değiştir: açı, güç veya malzeme farkını artır.','warn');return;}rec.measurements.push({key,result:reading,settings});if(rec.measurements.length>12)rec.measurements.shift();sceneStarted=performance.now();render();toast(rec.measurements.length>=2?'Karşılaştırma hazır. Sonucu açıkla!':'İlk ölçüm kaydedildi. Parametreyi değiştir.','success');}
function reason(i){const rec=state.labs[state.activeLab];if(rec.completed)return;rec.reason=i;render();}
function verifyReason(){const l=lab(state.activeLab),rec=state.labs[l.id];if(new Set(rec.measurements.map(x=>x.key)).size<2){toast('İki farklı koşulda ölçüm yap.','warn');return;}if(rec.reason===null){toast('Açıklamanı seç.','warn');return;}rec.reasonAttempts++;if(rec.reason===l.explainAnswer){rec.completed=true;render();toast('Keşif doğrulandı! '+l.concept+' alanı açıldı.','success');}else{render();toast('Ölçümleri tekrar incele. Açıklamanı değiştir.','warn');}}
function answerField(type,id){const transfer=type==='transfer',idx=transfer?state.transferIndex:state.classIndex,card=(transfer?TRANSFER_CARDS:CLASS_CARDS)[idx];if(!card)return;let currentMistake=transfer?'transferCurrentMistake':'classCurrentMistake';if(id!==card.field){state[currentMistake]=true;if(transfer)state.transferMistakes++;else state.classMistakes++;save();const target=$('#answer-feedback');if(target){target.innerHTML=`<div class="feedback warning">Henüz değil. <b>${field(id).name}</b> alanı ${field(id).description.toLocaleLowerCase('tr-TR')} Farklı bir bağlantı düşün.</div>`;}return;}
const arr=transfer?state.transferAnswers:state.classAnswers;arr.push({field:id,firstPass:!state[currentMistake]&&(!transfer?!state.classCurrentHint:true)});if(transfer)state.transferIndex++;else state.classIndex++;state[currentMistake]=false;if(!transfer)state.classCurrentHint=false;render();toast('Doğru eşleştirme: '+field(id).name,'success');}
function hint(){if(state.view!=='classify'||state.classAnswers.length>=8)return;if(state.classCurrentHint)return;state.classCurrentHint=true;state.hints++;render();}
function reset(){if(!confirm('Yalnız Fizik Atlası prototipindeki bu cihaz ilerlemesi sıfırlansın mı? StudyTracker verilerine dokunulmaz.'))return;try{localStorage.removeItem(STORAGE_KEY)}catch(_){}state=newProgress();render();}
function exportEvidence(){const blob=new Blob([JSON.stringify(documentEvidence(state),null,2)+'\n'],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fizik-atlasi-kazanim-raporu.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Rapor yerel dosya olarak indirildi.','success');}
function help(){alert('Fizik Atlası nasıl oynanır?\n\n1. Bir istasyon seç, fiziksel olaya dair tahminini yap.\n2. Kontrolleri ayarlayıp deneyi çalıştır.\n3. En az iki farklı koşulda ölçüm kaydet.\n4. Gözlemlerini açıklayarak istasyonu tamamla.\n5. Sekiz olayı fizik alanlarıyla eşleştir.\n6. Son görevi ipucusuz bitir, raporunu incele.\n\nMobilde tüm kontroller dokunmatik, klavyede Tab ve yön tuşları kullanılabilir.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.lab){state.activeLab=b.dataset.lab;render();return;}if(b.dataset.predict!==undefined){state.labs[state.activeLab].prediction=+b.dataset.predict;render();return;}if(b.dataset.reason!==undefined){reason(+b.dataset.reason);return;}if(b.dataset.setting){state.settings[state.activeLab][b.dataset.setting]=b.dataset.value;render();return;}if(b.dataset.class){answerField('class',b.dataset.class);return;}if(b.dataset.transfer){answerField('transfer',b.dataset.transfer);return;}switch(b.dataset.action){case 'start':state.missionStarted=true;render();break;case 'run':record();break;case 'verify-reason':verifyReason();break;case 'hint':hint();break;case 'reset':reset();break;case 'export':exportEvidence();break;case 'help':help();break;}});
document.addEventListener('input',e=>{const key=e.target.dataset.control;if(!key)return;const v=+e.target.value;state.settings[state.activeLab][key]=v;const out=$('#val-'+key);if(out)out.textContent=v+({angle:'°',position:'%',power:'%',temperature:'°C'}[key]||'');save()});
document.addEventListener('change',e=>{if(e.target.dataset.control)render()});

// Canvas presents physical effects; recorded numerical/qualitative results are calculated above.
const W=900,H=510;
function round(ctx,x,y,w,h,r=12){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function line(ctx,x1,y1,x2,y2,color,width=3,dash=[]){ctx.beginPath();ctx.setLineDash(dash);ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();ctx.setLineDash([])}
function txt(ctx,text,x,y,size=19,color='#cce0ef',weight='500'){ctx.font=`${weight} ${size}px system-ui, sans-serif`;ctx.fillStyle=color;ctx.fillText(text,x,y)}
function initCanvas(){const canvas=$('#labCanvas');if(!canvas)return;const resize=()=>{if(!canvas.isConnected)return;const r=canvas.getBoundingClientRect(),pixel=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.round(r.width*pixel));canvas.height=Math.max(1,Math.round(r.height*pixel));};resize();let drag=false;canvas.addEventListener('pointerdown',e=>{if(state.activeLab!=='magnet')return;drag=true;canvas.setPointerCapture(e.pointerId);magnetPointer(e,canvas);});canvas.addEventListener('pointermove',e=>{if(drag)magnetPointer(e,canvas);});canvas.addEventListener('pointerup',()=>{if(drag){drag=false;save();render();}});canvas.addEventListener('pointercancel',()=>{drag=false;});
const frame=now=>{if(!canvas.isConnected)return;const ctx=canvas.getContext('2d');if(now-lastFrame>28){draw(ctx,canvas,now);lastFrame=now;}raf=requestAnimationFrame(frame)};raf=requestAnimationFrame(frame);}
function magnetPointer(e,canvas){const r=canvas.getBoundingClientRect();const x=(e.clientX-r.left)/r.width*W;state.settings.magnet.position=Math.max(14,Math.min(68,Math.round((x-80)/7.4)));const slider=$('#ctrl-position');if(slider){slider.value=state.settings.magnet.position;const val=$('#val-position');if(val)val.textContent=state.settings.magnet.position+'%';}}
const ATLAS_MONTAGE_DATA={"lab":"data:image/webp;base64,","ramp":"data:image/webp;base64,","cube":"data:image/webp;base64,","support":"data:image/webp;base64,"};
const ATLAS_MONTAGE_IMAGES={};
for(const [id,url] of Object.entries(ATLAS_MONTAGE_DATA)){
 const img=new Image();img.src=url;ATLAS_MONTAGE_IMAGES[id]=img;
}
const ATLAS_MONTAGE_LAYOUT={
 ramp:{x:711.9,y:419.31,scale:.48,rotation:1,ax:.5,ay:.5},
 support:{x:1068.59,y:527.62,scale:.29,rotation:0,ax:.5,ay:.8},
 cube:{x:933.64,y:338.29,scale:.15,rotation:0,ax:.5,ay:.85}
};
function montageSprite(ctx,id,x,y,scale,rotation,ax,ay){
 const im=ATLAS_MONTAGE_IMAGES[id];if(!im||!im.complete||!im.naturalWidth)return;
 ctx.save();ctx.translate(x,y);ctx.rotate(rotation*Math.PI/180);ctx.scale(scale,scale);ctx.drawImage(im,-ax*im.width,-ay*im.height);ctx.restore();
}
function atlasMechanics(ctx,s,time){
 ctx.save();ctx.scale(W/1536,H/864);
 const bg=ATLAS_MONTAGE_IMAGES.lab;
 if(bg&&bg.complete&&bg.naturalWidth)ctx.drawImage(bg,0,0,1536,864);
 else{ctx.fillStyle='#122c42';ctx.fillRect(0,0,1536,864)}
 const a=ATLAS_MONTAGE_LAYOUT;
 // Reference framing from user-approved static assembly. Do not rotate perspective sprites independently.
 montageSprite(ctx,'support',a.support.x,a.support.y,a.support.scale,a.support.rotation,a.support.ax,a.support.ay);
 montageSprite(ctx,'ramp',a.ramp.x,a.ramp.y,a.ramp.scale,a.ramp.rotation,a.ramp.ax,a.ramp.ay);
 const m=calcExperiment('mechanics',s);
 const loopTime=Math.sqrt(2*4/Math.max(.01,m.a));
 const t=m.a>0.01 ? time%loopTime : 0;
 const progress=m.a>0.01?Math.min(1,.5*m.a*t*t/4):0;
 // On the pictured ramp, motion is from its raised right end toward its lower left end.
 // Visual path is calibrated in scene pixels independently of the physics model.
 const px=933.64-600*progress,py=338.29+202*progress;
 montageSprite(ctx,'cube',px,py,a.cube.scale,a.cube.rotation,a.cube.ax,a.cube.ay);
 ctx.fillStyle='rgba(7,20,32,.88)';ctx.beginPath();ctx.roundRect(18,18,570,93,16);ctx.fill();
 ctx.fillStyle='#edf8ff';ctx.font='bold 28px system-ui';ctx.fillText('HAREKET ATÖLYESİ',36,53);
 ctx.font='21px system-ui';ctx.fillStyle='#9af0dc';ctx.fillText('İvme: '+m.a.toFixed(2)+' m/s²  •  Hesaplanan eğim: '+s.angle+'°',36,88);
 ctx.fillStyle='rgba(7,20,32,.86)';ctx.beginPath();ctx.roundRect(25,755,1000,78,12);ctx.fill();
 ctx.font='23px system-ui';ctx.fillStyle='#fff4d8';ctx.fillText('Deney: Eğim ve yüzey türü hızı değiştirir. Görsel rampa 25° sabit referanstır.',43,799);
 ctx.restore();
}

function draw(ctx,canvas,now){const sx=canvas.width/W,sy=canvas.height/H;ctx.setTransform(sx,0,0,sy,0,0);ctx.clearRect(0,0,W,H);if(state.activeLab==='mechanics'){atlasMechanics(ctx,state.settings.mechanics,sceneStarted>0?(now-sceneStarted)/1000:(now/1000)%12);return;}const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#0c1c2c');g.addColorStop(.55,'#102436');g.addColorStop(1,'#071724');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='rgba(120,168,196,.068)';ctx.lineWidth=1;for(let x=0;x<W;x+=42){line(ctx,x,0,x,H,'rgba(130,180,208,.06)',1)}for(let y=0;y<H;y+=42)line(ctx,0,y,W,y,'rgba(130,180,208,.06)',1);
for(let i=0;i<32;i++){let x=(i*157+39)%W,y=(i*113+31)%H;ctx.fillStyle='rgba(187,235,255,.16)';ctx.fillRect(x,y,2,2)}
const time=sceneStarted>0?(now-sceneStarted)/1000:(now/1000);const id=state.activeLab,s=state.settings[id];ctx.save();if(id==='mechanics')drawMechanics(ctx,s,time);if(id==='optics')drawOptics(ctx,s,time);if(id==='magnet')drawMagnet(ctx,s,time,now);if(id==='thermal')drawThermal(ctx,s,time,now);ctx.restore();}
function drawMechanics(ctx,s,time){
 const theta=s.angle*Math.PI/180,baseX=190,baseY=417,rise=Math.sin(theta)*315,endX=727,endY=baseY-rise;
 ctx.fillStyle='#18364a';ctx.beginPath();ctx.moveTo(baseX,baseY);ctx.lineTo(endX,endY);ctx.lineTo(endX,baseY);ctx.closePath();ctx.fill();line(ctx,baseX,baseY,endX,endY,'#79b5c9',9);
 const m=calcExperiment('mechanics',s),track=4,period=m.a>0.01?Math.sqrt(2*track/m.a):4;
 // Each arrival teleports immediately to the top. No backwards movement or rewinding.
 const lapTime=m.a>0.01?(time%period):0,progress=m.a>0.01?.5*m.a*lapTime*lapTime/track:0;
 const px=endX-(endX-baseX)*progress,py=endY+(baseY-endY)*progress;
 ctx.save();ctx.translate(px,py-28);ctx.rotate(-Math.atan2(rise,endX-baseX));round(ctx,-25,-20,50,40,6);ctx.fillStyle='#ffcb79';ctx.fill();ctx.strokeStyle='#fff0c6';ctx.lineWidth=2;ctx.stroke();ctx.restore();
 txt(ctx,'RAMPADAKİ KUTU',95,130,21,'#deedff','700');txt(ctx,`Eğim ${s.angle}°  ·  ${s.surface==='rough'?'Pürüzlü':'Kaygan'}`,95,166,21,'#a7d9ed');
 txt(ctx,`İvme ${m.a.toFixed(2)} m/s²`,95,457,23,'#a7f3da','700');txt(ctx,m.a<.01?'Sürtünme nedeniyle kaymıyor':`KAYIYOR → Alt sınırda anında yeniden başlar`,365,489,17,'#c1dfeb');
}
function drawOptics(ctx,s,time){
 ctx.fillStyle='rgba(113,182,212,.16)';ctx.beginPath();ctx.moveTo(440,128);ctx.lineTo(580,385);ctx.lineTo(300,385);ctx.closePath();ctx.fill();ctx.strokeStyle='#a6cce6';ctx.lineWidth=4;ctx.stroke();
 const result=calcExperiment('optics',s);const palette={red:'#ff777e',orange:'#ffa26a',yellow:'#ffe38c',green:'#77e6ac',blue:'#79baff',violet:'#b69cff'};
 for(const ray of result.paths){const col=palette[ray.color];if(ray.miss){line(ctx,ray.source[0],ray.source[1],ray.source[0]+ray.input[0]*700,ray.source[1]+ray.input[1]*700,col,3);continue;}
 line(ctx,...ray.source,...ray.entry,col,4);if(ray.exit){line(ctx,...ray.entry,...ray.exit,col,4);if(ray.outside){const ext=470;line(ctx,...ray.exit,ray.exit[0]+ray.outside[0]*ext,ray.exit[1]+ray.outside[1]*ext,col,4)}else{line(ctx,...ray.exit,ray.exit[0]-ray.inside[0]*220,ray.exit[1]-ray.inside[1]*220,col,4)}}}
 txt(ctx,'IŞIN KIRILMASI',90,106,23,'#e8f4ff','700');txt(ctx,`Giriş yönü: ${s.angle}°`,90,145,21,'#b9dcf4');
 txt(ctx,'HAVA → CAM → HAVA',90,440,18,'#9de6d1','700');txt(ctx,'Açıyı değiştir: Snell yasasına göre yön değişir',90,482,17,'#c5dcef');
}
function drawMagnet(ctx,s,time,now){
 const x=80+7.4*s.position,y=270,power=s.power/100,m=calcExperiment('magnet',s);
 // Relative response to a distance-dependent dipole-like gradient; start fresh on each run.
 const pull=Math.min(1,time/2.2)*m.strength*200;
 for(let ring=1;ring<=5;ring++){ctx.beginPath();ctx.ellipse(x,y,ring*(32+power*22),ring*(26+power*19),0,0,Math.PI*2);ctx.strokeStyle=`rgba(105,236,211,${Math.max(.025,.22*power-ring*.028)})`;ctx.lineWidth=2;ctx.stroke()}
 ctx.save();ctx.translate(x,y);round(ctx,-64,-30,128,60,10);ctx.clip();ctx.fillStyle='#df6f76';ctx.fillRect(-64,-30,64,60);ctx.fillStyle='#6cb1dd';ctx.fillRect(0,-30,64,60);ctx.restore();
 txt(ctx,'N',x-36,y+9,28,'#fff','800');txt(ctx,'S',x+22,y+9,28,'#fff','800');
 const bx=697-pull;ctx.beginPath();ctx.fillStyle='#acd9f2';ctx.arc(bx,270,30,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f0feff';ctx.lineWidth=3;ctx.stroke();
 round(ctx,650,375,88,54,6);ctx.fillStyle='#a88b65';ctx.fill();txt(ctx,'DEMİR',645,219,18,'#e9f7ff','700');txt(ctx,'TAHTA',650,457,18,'#e5eddd','700');
 txt(ctx,'MANYETİK ÇEKİM',80,105,22,'#e9f7ff','700');txt(ctx,`Güç ayarı: %${s.power}`,80,141,18,'#a2dbf4');
 txt(ctx,`Bağıl kuvvet: ${Math.round(m.strength*100)} / 100`,80,475,21,'#9ceacd','700');txt(ctx,'Uzaklık arttıkça kuvvet kesintisiz azalır',80,501,17,'#bddeeb');
}
function drawThermal(ctx,s,time,now){
 const t=Math.min(40,time),metal=s.material==='metal',model=thermalAtTime(s,t);
 ctx.fillStyle='#203649';round(ctx,108,370,670,47,10);ctx.fill();
 // Left = heat source; right = sensor on identical length rods.
 round(ctx,190,231,555,92,14);ctx.fillStyle=metal?'#608baf':'#82684e';ctx.fill();
 const warm=Math.max(0,Math.min(1,(model.tip-20)/Math.max(1,s.temperature-20)));
 ctx.save();round(ctx,190,231,555*warm,92,12);ctx.fillStyle='#f99c6c';ctx.fill();ctx.restore();
 ctx.beginPath();ctx.arc(187,277,48,0,Math.PI*2);ctx.fillStyle='#ffad75';ctx.fill();
 // Explicit labeled source and far-end thermometer; show numeric, not only color.
 line(ctx,739,223,739,320,'#d9ecf7',4);ctx.beginPath();ctx.arc(739,329,14,0,Math.PI*2);ctx.fillStyle='#ffce9b';ctx.fill();
 txt(ctx,'ISI KAYNAĞI',100,125,19,'#ffcf96','700');txt(ctx,`${s.temperature} °C`,100,160,31,'#ffe2c2','700');
 txt(ctx,metal?'METAL ÇUBUK':'AHŞAP ÇUBUK',375,198,22,'#e6f6ff','700');
 txt(ctx,'UÇTAKİ TERMOMETRE',522,127,19,'#acd9ec','700');txt(ctx,`${model.tip.toFixed(1)} °C`,552,164,29,'#b1f0d6','700');
 txt(ctx,`Geçen süre: ${t.toFixed(1)} saniye`,100,451,20,'#c5e6f7','700');
 txt(ctx,metal?'Metal: enerji uca daha çabuk ulaşır':'Ahşap: enerji uca daha yavaş ulaşır',100,486,19,'#b0ead5','700');
}

render();
